{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.FINAL_ESHIP_TRACKING AS ( WITH converted AS ( SELECT e.order_status AS eship_status, UPPER(t.value:invoice_number::string) AS unique_order_id, UPPER(e.details:tag::STRING) AS status, UPPER(e.slug) AS courier_partner, UPPER(e.customer_referenc) AS combined_order_id, e.details:pod_link::STRING AS pod_link, e.is_reverse::BOOLEAN AS is_reverse, CONVERT_TIMEZONE( \'UTC\', \'Asia/Kolkata\', TO_TIMESTAMP_NTZ(SUBSTRING(e.date::STRING, 6, 20), \'DD MON YYYY HH24:MI:SS\') ) AS logistics_created_timestamp, TO_TIMESTAMP_NTZ( SUBSTRING(e.details:checkpoints[0]:\"date\"::STRING, 6, 20), \'DD MON YYYY HH24:MI:SS\' ) AS last_updated_timestamp, TO_TIMESTAMP_NTZ( TO_TIMESTAMP_TZ(e.details:delivery_date::STRING, \'DY, DD MON YYYY HH24:MI:SS TZD\') ) AS logistics_delivery_timestamp, ( TO_TIMESTAMP_NTZ( TO_TIMESTAMP_TZ(e.details:expected_delivery_date::STRING, \'DY, DD MON YYYY HH24:MI:SS TZD\') ) - INTERVAL \'11 hours\' ) AS logistics_expected_delivery_date, e.pickup_attempts::NUMBER AS pickup_attempts, e.pickup_meta:pickup_request::BOOLEAN AS pickup_request, e.delivery_attempts::NUMBER AS delivery_attempts, CASE WHEN NULLIF(e.first_ofd_date,\'\') ILIKE \'%GMT%\' THEN TO_TIMESTAMP_NTZ( TO_TIMESTAMP_TZ(e.first_ofd_date::STRING, \'DY, DD MON YYYY HH24:MI:SS TZD\') ) ELSE TO_TIMESTAMP_NTZ(NULLIF(e.first_ofd_date,\'\')) END AS first_ofd_date, CASE WHEN NULLIF(e.latest_ofd_date,\'\') ILIKE \'%GMT%\' THEN TO_TIMESTAMP_NTZ( TO_TIMESTAMP_TZ(e.latest_ofd_date::STRING, \'DY, DD MON YYYY HH24:MI:SS TZD\') ) ELSE TO_TIMESTAMP_NTZ(NULLIF(e.latest_ofd_date,\'\')) END AS latest_ofd_date, CASE WHEN LOWER(e.slug) LIKE \'%gati%\' THEN TRY_TO_TIMESTAMP_NTZ( SUBSTRING( e.details:checkpoints[array_size(e.details:checkpoints)-1]:date::STRING, 6, 20 ), \'DD MON YYYY HH24:MI:SS\' ) WHEN TRY_TO_TIMESTAMP_NTZ( e.tracking_pick_date, \'YYYY-MM-DD\"T\"HH24:MI:SS\' ) IS NOT NULL THEN TRY_TO_TIMESTAMP_NTZ( e.tracking_pick_date, \'YYYY-MM-DD\"T\"HH24:MI:SS\' ) WHEN NULLIF(e.tracking_pick_date,\'\') ILIKE \'%GMT%\' THEN TO_TIMESTAMP_NTZ( TO_TIMESTAMP_TZ( e.tracking_pick_date, \'DY, DD MON YYYY HH24:MI:SS TZD\' ) ) WHEN TRY_TO_TIMESTAMP_NTZ( REGEXP_REPLACE(e.tracking_pick_date, \'^.*, \', \'\'), \'DD MON YYYY HH24:MI:SS\' ) IS NOT NULL THEN TRY_TO_TIMESTAMP_NTZ( REGEXP_REPLACE(e.tracking_pick_date, \'^.*, \', \'\'), \'DD MON YYYY HH24:MI:SS\' ) ELSE TRY_TO_TIMESTAMP_NTZ(NULLIF(e.tracking_pick_date,\'\')) END AS tracking_pick_date, UPPER(e.active::STRING) AS live_status, e.entered_weight:unit::STRING AS weight_unit, e.entered_weight:value::FLOAT AS weight_value, e.label_meta:box_count::NUMBER AS box_count, e.customer_referenc::STRING AS customer_reference, UPPER(e.order_details:receiver_address:city::STRING) AS receiver_city, TRIM(REGEXP_REPLACE(e.order_details:receiver_address:contact_name::STRING, \'\s*-\s*[^-]*$\', \'\')) AS receiver_company_name, e.order_details:receiver_address:phone::STRING AS receiver_phone, e.order_details:receiver_address:postal_code::STRING AS receiver_postal_code, UPPER(e.order_details:receiver_address:state::STRING) AS receiver_state, e.order_details:receiver_address:street1::STRING AS receiver_street1, e.order_details:receiver_address:street2::STRING AS receiver_street2, e.order_details:receiver_address:street3::STRING AS receiver_street3, UPPER(e.order_details:receiver_address:type::STRING) AS receiver_type, UPPER(e.account_info:description::STRING) AS transporter_name, e.invoice_details:amount::NUMBER AS invoice_amount, e.tracking_link::STRING AS tracking_link, e.tracking_status::STRING AS tracking_status, e.tracking_status_code::STRING AS tracking_status_code, e.tracking_sub_status::STRING AS tracking_sub_status, e.invoice_details:ewaybill_number::STRING AS invoice_ewaybill_number, e.invoice_details:invoice_date::STRING AS invoice_date, e.invoice_details:invoice_link::STRING AS invoice_link, e.invoice_details:invoice_number::STRING AS invoice_number, e.invoice_details:total_invoice_amount::NUMBER AS total_invoice_amount, e.tracking_return_pick_date, e.tracking_return_delivery_date, e.tracking_return_expected_delivery, e.tracking_latest_location, e.tracking_latest_message, e.meta_collection:area_code::STRING AS area_code, e.meta_collection:cust_code::STRING AS customer_code, e.meta_collection:dst_code::STRING AS destination_code, e.meta_collection:dst_loc::STRING AS destination_location, e.meta_collection:src_code::STRING AS source_code, e.meta_collection:src_loc::STRING AS source_location, e.meta_collection:product_code::STRING AS product_code, e.parcel_contents, e.payment_mode:favour_name::STRING AS payment_favour_name, e.payment_mode:mode_option::STRING AS payment_mode_option, e.webhook_triggered_states[0]::STRING AS webhook_triggered_states, e.label_meta:master_label_count::NUMBER AS master_label_count, e.label_meta:url::STRING AS label_url, e.labels_downloaded::BOOLEAN AS labels_downloaded, e.package_count::NUMBER AS package_count, e.purpose::STRING AS purpose, e.received_by::STRING AS received_by, e.return_initiate_date::STRING AS return_initiate_date, e.return_reason::STRING AS return_reason, e.service_type::STRING AS service_type, e.shipment_type::STRING AS shipment_type, e.special_instruction::STRING AS special_instruction, e.custom_fields:total_shipment_quantity::NUMBER AS total_shipment_quantity, e.details:shipment_status AS random_status, e.awb AS tracking_number, e.details:checkpoints[0]:\"city\"::STRING AS last_checkpoint_city, e.details:checkpoints[0]:\"remark\"::STRING AS last_checkpoint_remark, e.details:checkpoints[0]:\"state\"::STRING AS last_checkpoint_state, e.details:checkpoints[0]:\"subtag\"::STRING AS last_checkpoint_subtag, e.details:checkpoints[0]:\"tag\"::STRING AS last_checkpoint_tag, CASE WHEN UPPER(e.order_details:receiver_address:state::STRING) IN (\'DADRA AND NAGAR HAVELI\',\'GUJARAT\',\'MADHYA PRADESH\',\'CHHATISGARH\',\'GOA\',\'MAHARASHTRA\') THEN \'WEST\' WHEN UPPER(e.order_details:receiver_address:state::STRING) IN (\'ANDHRA PRADESH\',\'KARNATAKA\',\'PONDICHERRY\',\'TAMIL NADU\',\'TELANGANA\',\'KERALA\') THEN \'SOUTH\' WHEN UPPER(e.order_details:receiver_address:state::STRING) IN (\'CHANDIGARH\',\'DELHI\',\'HARYANA\',\'HIMACHAL PRADESH\',\'JAMMU AND KASHMIR\', \'PUNJAB\',\'RAJASTHAN\',\'UTTAR PRADESH\',\'UTTARAKHAND\') THEN \'NORTH\' WHEN UPPER(e.order_details:receiver_address:state::STRING) IN (\'ARUNACHAL PRADESH\',\'ASSAM\',\'BIHAR\',\'JHARKHAND\',\'MEGHALAYA\',\'MIZORAM\', \'NAGALAND\',\'ODISHA\',\'SIKKIM\',\'TRIPURA\',\'WEST BENGAL\') THEN \'EAST\' ELSE \'UNMAPPED\' END AS zone FROM snitch_db.maplemonk.eshipz_final_get_tracking e, LATERAL FLATTEN(input => e.gst_invoices) t ), sto_data AS ( SELECT to_party, from_party, bill_no, order_no, trans_name, vouch_code, new_bill_no, sku, item_group_name_1, item_quantity FROM snitch_db.maplemonk.logic_final_sto ), final AS ( SELECT * FROM converted c LEFT JOIN sto_data sd ON c.unique_order_id = sd.new_bill_no ), uc AS ( WITH test AS ( SELECT a.*, b.store, ROW_NUMBER() OVER (PARTITION BY a.order_name ORDER BY a.last_updated DESC) AS rn FROM snitch_db.maplemonk.warehouse_sla_performance a LEFT JOIN warehouse_b2b_performance b ON a.order_name = b.order_name WHERE a.marketplace_mapped = \'STORE\' ) SELECT * FROM test a WHERE rn = 1 ), final1 AS ( SELECT f.*, uc.store, b.best_tat, b.lane_classification, uc.order_timestamp, uc.order_type, uc.manifested_timestamp, DAYNAME(uc.order_timestamp) AS order_dow, CASE WHEN uc.order_type = \'FRESH\' THEN LEFT(b.fresh_order_cutoff, 3) WHEN uc.order_type = \'RPL\' THEN LEFT(b.rpl_order_cutoff, 3) END AS target_order_day, CASE WHEN uc.order_type = \'FRESH\' THEN RIGHT(b.fresh_order_cutoff,4) WHEN uc.order_type = \'RPL\' THEN RIGHT(b.rpl_order_cutoff, 4) END AS target_order_cutoff, DAYNAME(uc.manifested_timestamp) AS manifested_dow, CASE WHEN uc.order_type = \'FRESH\' THEN LEFT(b.fresh_handover_day, 3) WHEN uc.order_type = \'RPL\' THEN LEFT(b.rpl_handover_day, 3) END AS target_handover_day, CASE WHEN uc.order_type = \'FRESH\' THEN RIGHT(b.fresh_tat, 4) WHEN uc.order_type = \'RPL\' THEN RIGHT(b.rpl_tat, 4) END AS target_handover_cutoff, DAYOFWEEKISO(uc.order_timestamp) - DECODE(target_order_day,\'Mon\',1,\'Tue\',2,\'Wed\',3,\'Thu\',4,\'Fri\',5,\'Sat\',6,\'Sun\',7) AS dow_diff, DAYOFWEEKISO(uc.manifested_timestamp) - DECODE(target_handover_day,\'Mon\',1,\'Tue\',2,\'Wed\',3,\'Thu\',4,\'Fri\',5,\'Sat\',6,\'Sun\',7) AS dow_diff_handover, CASE WHEN target_order_day = \'Mon\' THEN CASE WHEN DAYOFWEEKISO(order_timestamp) IN (5,6,7,1) THEN \'OK\' ELSE \'BREACHED\' END ELSE CASE WHEN MOD( DECODE(target_order_day,\'Mon\',1,\'Tue\',2,\'Wed\',3,\'Thu\',4,\'Fri\',5,\'Sat\',6,\'Sun\',7) - DAYOFWEEKISO(order_timestamp), 7 ) IN (0,1,2) THEN \'OK\' ELSE \'BREACHED\' END END AS placement_window_status FROM final f LEFT JOIN uc ON f.order_no = uc.order_name LEFT JOIN distribution_rulebook b ON f.to_party = b.store_name AND ( (uc.warehouse_name IN (\'SAPL-WH2\', \'SAPL-WH1\') AND b.wh = \'South WH\') OR (uc.warehouse_name IN (\'SAPL-NORTH-TAURU\') AND b.wh = \'North WH\') ) ), calc AS ( SELECT f1.*, DECODE(f1.target_order_day, \'Mon\',1,\'Tue\',2,\'Wed\',3,\'Thu\',4,\'Fri\',5,\'Sat\',6,\'Sun\',7 ) AS target_order_dow_num, DAYOFWEEKISO(f1.order_timestamp) AS order_dow_num, CASE WHEN f1.target_order_cutoff ILIKE \'%AM\' THEN CASE WHEN TRY_TO_NUMBER(TRIM(REPLACE(UPPER(f1.target_order_cutoff),\'AM\',\'\'))) = 12 THEN 0 ELSE TRY_TO_NUMBER(TRIM(REPLACE(UPPER(f1.target_order_cutoff),\'AM\',\'\'))) END WHEN f1.target_order_cutoff ILIKE \'%PM\' THEN CASE WHEN TRY_TO_NUMBER(TRIM(REPLACE(UPPER(f1.target_order_cutoff),\'PM\',\'\'))) = 12 THEN 12 ELSE TRY_TO_NUMBER(TRIM(REPLACE(UPPER(f1.target_order_cutoff),\'PM\',\'\'))) + 12 END END AS order_cutoff_hour, DATEADD( hour, order_cutoff_hour, DATEADD( day, -((DAYOFWEEKISO(f1.order_timestamp) - DECODE(f1.target_order_day,\'Mon\',1,\'Tue\',2,\'Wed\',3,\'Thu\',4,\'Fri\',5,\'Sat\',6,\'Sun\',7) + 7) % 7), DATE_TRUNC(\'day\', f1.order_timestamp) ) ) AS order_cutoff_ts, CASE WHEN f1.order_timestamp IS NULL OR f1.target_order_day IS NULL OR f1.target_order_cutoff IS NULL THEN NULL WHEN f1.placement_window_status = \'BREACHED\' THEN \'BREACHED\' WHEN f1.order_timestamp > order_cutoff_ts THEN \'BREACHED\' ELSE \'WITHIN_SLA\' END AS order_placement_sla, CASE WHEN f1.target_handover_cutoff ILIKE \'%AM\' THEN CASE WHEN TRY_TO_NUMBER(TRIM(REPLACE(UPPER(f1.target_handover_cutoff),\'AM\',\'\'))) = 12 THEN 0 ELSE TRY_TO_NUMBER(TRIM(REPLACE(UPPER(f1.target_handover_cutoff),\'AM\',\'\'))) END WHEN f1.target_handover_cutoff ILIKE \'%PM\' THEN CASE WHEN TRY_TO_NUMBER(TRIM(REPLACE(UPPER(f1.target_handover_cutoff),\'PM\',\'\'))) = 12 THEN 12 ELSE TRY_TO_NUMBER(TRIM(REPLACE(UPPER(f1.target_handover_cutoff),\'PM\',\'\'))) + 12 END END AS handover_cutoff_hour, CASE WHEN f1.order_timestamp IS NULL THEN NULL WHEN order_placement_sla = \'WITHIN_SLA\' AND f1.target_handover_day IS NOT NULL AND f1.target_handover_cutoff IS NOT NULL THEN DATEADD( hour, CASE WHEN f1.target_handover_cutoff ILIKE \'%AM\' THEN CASE WHEN TRY_TO_NUMBER(TRIM(REPLACE(UPPER(f1.target_handover_cutoff),\'AM\',\'\'))) = 12 THEN 0 ELSE TRY_TO_NUMBER(TRIM(REPLACE(UPPER(f1.target_handover_cutoff),\'AM\',\'\'))) END WHEN f1.target_handover_cutoff ILIKE \'%PM\' THEN CASE WHEN TRY_TO_NUMBER(TRIM(REPLACE(UPPER(f1.target_handover_cutoff),\'PM\',\'\'))) = 12 THEN 12 ELSE TRY_TO_NUMBER(TRIM(REPLACE(UPPER(f1.target_handover_cutoff),\'PM\',\'\'))) + 12 END END, DATEADD( day, MOD( DECODE(f1.target_handover_day,\'Mon\',1,\'Tue\',2,\'Wed\',3,\'Thu\',4,\'Fri\',5,\'Sat\',6,\'Sun\',7) - DAYOFWEEKISO(f1.order_timestamp), 7 ), DATE_TRUNC(\'day\', f1.order_timestamp) ) ) WHEN order_placement_sla = \'BREACHED\' THEN CASE WHEN EXTRACT(HOUR FROM f1.order_timestamp) < 9 THEN DATE_TRUNC(\'day\', f1.order_timestamp) + INTERVAL \'18 hour\' WHEN EXTRACT(HOUR FROM f1.order_timestamp) < 16 THEN DATE_TRUNC(\'day\', f1.order_timestamp) + INTERVAL \'1 day\' + INTERVAL \'5 hour\' ELSE DATE_TRUNC(\'day\', f1.order_timestamp) + INTERVAL \'1 day\' + INTERVAL \'18 hour\' END ELSE NULL END AS handover_deadline_ts, CASE WHEN f1.manifested_timestamp IS NULL AND handover_deadline_ts IS NULL THEN \'FUTURE SLA\' WHEN f1.manifested_timestamp IS NULL AND handover_deadline_ts < CURRENT_TIMESTAMP THEN \'BREACHED-PENDING FOR PROCESS\' WHEN f1.manifested_timestamp IS NULL AND handover_deadline_ts >= CURRENT_TIMESTAMP THEN \'FUTURE SLA\' WHEN f1.manifested_timestamp > handover_deadline_ts THEN \'BREACHED\' ELSE \'WITHIN_SLA\' END AS handover_sla, CASE WHEN EXTRACT(hour FROM logistics_created_timestamp) < 18 THEN DATE_TRUNC(\'day\', logistics_created_timestamp) + INTERVAL \'22 hour\' ELSE DATE_TRUNC(\'day\', logistics_created_timestamp + INTERVAL \'1 day\') + INTERVAL \'22 hour\' END AS pickup_tat, CASE WHEN is_reverse = FALSE THEN DATEADD(\'day\', best_tat, tracking_pick_date) WHEN tracking_pick_date IS NULL THEN NULL WHEN is_reverse = TRUE THEN CASE WHEN UPPER(receiver_company_name) LIKE \'%WH - NORTH%\' THEN DATE_TRUNC(\'day\', DATEADD(\'day\', COALESCE( (CASE WHEN UPPER(from_party) = \'SNITCH - COCO - JAYANAGAR\' THEN 5 WHEN UPPER(from_party) = \'SNITCH - FOCO - MBH\' THEN 5 WHEN UPPER(from_party) = \'SNITCH - FOCO - VR MALL\' THEN 5 WHEN UPPER(from_party) = \'SNITCH - COFO - BRIGADE ROAD\' THEN 5 WHEN UPPER(from_party) = \'SNITCH - FOCO - TRION\' THEN 3 WHEN UPPER(from_party) = \'SNITCH - FOCO - EVA\' THEN 3 WHEN UPPER(from_party) = \'SNITCH - COCO - HSR LAYOUT\' THEN 5 WHEN UPPER(from_party) = \'SNITCH - COCO - BEL ROAD\' THEN 5 WHEN UPPER(from_party) = \'SNITCH - FOCO - GANDHI NAGAR\' THEN 3 WHEN UPPER(from_party) = \'SNITCH - COFO - SARATH CITY\' THEN 4 WHEN UPPER(from_party) = \'SNITCH - COFO - AMANORA\' THEN 3 WHEN UPPER(from_party) = \'SNITCH - FOCO - SHYAMAL\' THEN 3 WHEN UPPER(from_party) = \'SNITCH - COCO - KORMANGLA\' THEN 5 WHEN UPPER(from_party) = \'SNITCH - COFO - KUKATPALLY\' THEN 4 WHEN UPPER(from_party) = \'SNITCH - FOCO - EARTH EUPHORIA\' THEN 3 WHE